export const SingleSelectContract: Story = {
  render: () => {
    const [selected, setSelected] = useState("Compute");
    const items = useMemo(
      () =>
        options.map((option) => ({
          id: option.id,
          value: option.label,
          label: option.label,
          selectable: true,
          onClick: () => setSelected(option.label),
        })),
      [],
    );
    return (
      <div style={{ width: 300, display: "grid", gap: 8 }}>
        <IDSAIDropdownComboBox
          selectionMode="single"
          selectedValues={[selected]}
          trigger={<Trigger value={selected} />}
          items={items}
          showSearch
          matchTriggerWidth
          defaultOpen
          maxHeight={220}
        />
      </div>
    );
  },
};

export const MultiSelectContract: Story = {
  render: () => {
    const [selected, setSelected] = useState<string[]>(["Storage", "Compute"]);
    const items = useMemo(
      () =>
        options.map((option) => ({
          id: option.id,
          value: option.label,
          label: option.label,
          selectable: true,
          onClick: () =>
            setSelected((prev) =>
              prev.includes(option.label)
                ? prev.filter((entry) => entry !== option.label)
                : [...prev, option.label],
            ),
        })),
      [],
    );
    return (
      <div style={{ width: 300, display: "grid", gap: 8 }}>
        <IDSAIDropdownComboBox
          selectionMode="multi"
          selectedValues={selected}
          trigger={<Trigger value={selected.join(", ")} placeholder="Select products" />}
          items={items}
          showSearch
          matchTriggerWidth
          defaultOpen
          maxHeight={220}
        />
      </div>
    );
  },
};

